package com.example.blades360;

import android.content.*;
import android.app.Activity;
import android.graphics.*;
import android.net.Uri;
import android.view.*;
import android.view.inputmethod.InputMethodManager;
import android.widget.*;
import org.json.*;
import java.io.*;
import java.util.*;

/** Drawn media guide, durable playlists and capture actions. */
final class MediaTools {
  final AppMedia media;
  final MainActivity a;
  boolean open;
  int screen,selection,offset;
  String playlist="",queueName="";
  AppMedia.Item capture;
  BladesKeyboard editor;
  final Random random=new Random();
  MediaTools(AppMedia m){media=m;a=m.a;}
  JSONObject playlists(){try{return new JSONObject(a.library.prefs.getString("music_playlists","{}"));}catch(JSONException e){return new JSONObject();}}
  void save(JSONObject value){a.library.prefs.edit().putString("music_playlists",value.toString()).apply();media.changed();}
  ArrayList<String> names(){ArrayList<String> n=new ArrayList<>();Iterator<String> keys=playlists().keys();while(keys.hasNext())n.add(keys.next());n.sort(String::compareToIgnoreCase);return n;}
  void show(int which){open=true;screen=which;selection=offset=0;a.dashboard.stopStick();a.dashboard.requestFocus();media.changed();}
  void now(){show(0);if(media.songs.isEmpty()&&!media.loading)media.scanMusic();}
  void gallery(){if(media.items.isEmpty())return;capture=media.items.get(media.index);show(4);}
  boolean back(){if(editor!=null){closeEditor();return true;}if(!open)return false;if(screen==0||screen==4){open=false;}else if(screen==2||screen==3){show(1);}else if(screen==5){show(capture==null?2:4);}else show(0);media.changed();return true;}
  int slots(){return Math.max(3,(int)((a.dashboard.H-340)/45));}
  void move(int delta){selection=Math.max(0,Math.min(labels().size()-1,selection+delta));if(selection<offset)offset=selection;if(selection>=offset+slots())offset=selection-slots()+1;media.changed();}
  boolean key(int key,KeyEvent e){if(key==99&&media.recording()){if(e.getRepeatCount()==0)media.stopRecording();return true;}if(key==109||key==82){if(e.getRepeatCount()==0){if(open)open=false;else now();media.changed();}return true;}if(key==106||key==120){if(e.getRepeatCount()==0)media.capture();return true;}if(key==107){if(e.getRepeatCount()==0){if(media.recording())media.stopRecording();else media.startRecording();}return true;}if(!open)return false;if(e.getRepeatCount()>0&&(key==96||key==99||key==100))return true;if(key==19)move(-1);else if(key==20)move(1);else if(key==96||key==23||key==66)activate();else if(key==97||key==4)back();else if(key==21||key==22){if(screen==0)media.seek(key==21?-10000:10000);}else if(key==102||key==103){advance(key==102?-1:1,false);}return true;}
  ArrayList<String> labels(){ArrayList<String> rows=new ArrayList<>();if(screen==0){Collections.addAll(rows,media.player!=null&&media.prepared&&media.player.isPlaying()?"Pause":"Play","Previous track","Next track","Shuffle: "+(a.library.prefs.getBoolean("music_shuffle",false)?"On":"Off"),"Repeat: "+new String[]{"Off","All","One"}[repeat()],"Playlists","Open music library","Take screenshot",media.recording()?"Stop UI recording":"Record this app","Close","Stop playback");}else if(screen==1){rows.add("Create playlist");for(String n:names())rows.add(n);rows.add("All tracks (clear playlist queue)");}else if(screen==2){Collections.addAll(rows,"Play playlist","Add selected track","Browse / remove tracks","Rename playlist","Delete playlist");}else if(screen==3){JSONArray entries=playlists().optJSONArray(playlist);if(entries!=null)for(int i=0;i<entries.length();i++)rows.add(title(entries.optString(i)));if(rows.isEmpty())rows.add("Playlist is empty");}else if(screen==4){Collections.addAll(rows,"View","Rename","Share","Delete");}else if(screen==5){Collections.addAll(rows,"Cancel","Delete permanently");}return rows;}
  int repeat(){return Math.max(0,Math.min(2,a.library.prefs.getInt("music_repeat",0)));}
  String title(String uri){for(AppMedia.Item s:media.songs)if(s.uri.toString().equals(uri))return s.name;return "Unavailable track";}
  ArrayList<Integer> queue(){ArrayList<Integer> result=new ArrayList<>();JSONArray entries=queueName.isEmpty()?null:playlists().optJSONArray(queueName);if(entries==null){for(int i=0;i<media.songs.size();i++)result.add(i);}else for(int i=0;i<entries.length();i++){String uri=entries.optString(i);for(int j=0;j<media.songs.size();j++)if(media.songs.get(j).uri.toString().equals(uri)){result.add(j);break;}}return result;}
  void advance(int direction,boolean completed){ArrayList<Integer> q=queue();int next=MediaQueue.next(q,media.playing,direction,completed,repeat(),a.library.prefs.getBoolean("music_shuffle",false),random);if(next<0){media.stopMusic();media.status=q.isEmpty()?"No available tracks in this playlist":"Playlist finished";media.changed();return;}media.stopMusic();media.play(next);}
  void activate(){if(screen==0){switch(selection){case 0:if(media.songs.isEmpty()){open=false;media.open(0);}else media.play(media.playing>=0?media.playing:Math.max(0,media.index));break;case 1:advance(-1,false);break;case 2:advance(1,false);break;case 3:a.library.prefs.edit().putBoolean("music_shuffle",!a.library.prefs.getBoolean("music_shuffle",false)).apply();break;case 4:a.library.prefs.edit().putInt("music_repeat",(repeat()+1)%3).apply();break;case 5:show(1);break;case 6:open=false;media.open(0);break;case 7:media.capture();break;case 8:if(media.recording())media.stopRecording();else media.startRecording();break;case 9:open=false;break;case 10:media.stopMusic();media.status="Stopped";break;}}else if(screen==1){ArrayList<String> n=names();if(selection==0)edit("New playlist","",value->{JSONObject p=playlists();if(p.has(value)){media.status="A playlist with that name already exists";return;}try{p.put(value,new JSONArray());save(p);playlist=value;show(2);}catch(JSONException ignored){}});else if(selection<=n.size()){playlist=n.get(selection-1);show(2);}else{queueName="";media.status="Playing from all tracks";show(0);}}else if(screen==2){JSONObject p=playlists();JSONArray tracks=p.optJSONArray(playlist);if(tracks==null){show(1);return;}if(selection==0){queueName=playlist;ArrayList<Integer> q=queue();if(q.isEmpty())media.status="This playlist has no available tracks";else{media.stopMusic();media.play(q.get(0));show(0);}}else if(selection==1){int n=media.active&&media.mode==0?media.index:media.playing;if(n<0||n>=media.songs.size()){media.status="Select a track in Music first";}else{String uri=media.songs.get(n).uri.toString();boolean found=false;for(int i=0;i<tracks.length();i++)if(uri.equals(tracks.optString(i)))found=true;if(!found)tracks.put(uri);save(p);media.status=found?"Track is already in playlist":"Track added to "+playlist;}}else if(selection==2)show(3);else if(selection==3)edit("Rename playlist",playlist,value->{JSONObject pl=playlists();if(pl.has(value)&&!value.equals(playlist)){media.status="A playlist with that name already exists";return;}try{Object data=pl.remove(playlist);pl.put(value,data);if(queueName.equals(playlist))queueName=value;playlist=value;save(pl);}catch(JSONException ignored){}});else{capture=null;show(5);}}else if(screen==3){JSONObject p=playlists();JSONArray tracks=p.optJSONArray(playlist);if(tracks!=null&&selection<tracks.length()){tracks.remove(selection);save(p);selection=Math.max(0,Math.min(selection,tracks.length()-1));media.status="Track removed from playlist";}}else if(screen==4){if(capture==null){open=false;return;}if(selection==0){open=false;if(capture.movie)media.openVideo(capture);else media.preview=true;}else if(selection==1)edit("Rename capture",capture.name.replaceFirst("(?i)\\.(png|mp4)$",""),value->renameCapture(value));else if(selection==2)share();else show(5);}else if(screen==5){if(selection==0){show(capture==null?2:4);}else if(capture!=null){if(capture.file.delete()){media.thumbs.remove(capture.uri.toString());media.status="Capture deleted";}else media.status="Could not delete capture";open=false;media.preview=false;media.refresh();}else{JSONObject p=playlists();p.remove(playlist);if(queueName.equals(playlist))queueName="";save(p);show(1);}}media.changed();}
  void renameCapture(String value){if(capture==null)return;String base=value.replaceFirst("(?i)\\.(png|mp4)$","");if(!base.startsWith("Blades-"))base="Blades-"+base;File target=new File(capture.file.getParentFile(),base+(capture.movie?".mp4":".png"));if(target.equals(capture.file))return;if(target.exists()){media.status="A capture with that name already exists";return;}if(capture.file.renameTo(target)){media.thumbs.remove(capture.uri.toString());capture=new AppMedia.Item(target.getName(),Uri.fromFile(target),target,capture.movie);media.status="Capture renamed";media.refresh();}else media.status="Could not rename capture";}
  void share(){if(capture==null||!capture.file.isFile())return;Uri uri=new Uri.Builder().scheme("content").authority("com.example.blades360.media").appendPath(capture.movie?"movies":"pictures").appendPath(capture.name).build();Intent send=new Intent(Intent.ACTION_SEND).setType(capture.movie?"video/mp4":"image/png").putExtra(Intent.EXTRA_STREAM,uri).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);send.setClipData(ClipData.newUri(a.getContentResolver(),capture.name,uri));try{a.startActivity(Intent.createChooser(send,"Share capture"));}catch(Exception e){media.status="No app can share this capture";}}
  void edit(String title,String initial,java.util.function.Consumer<String> action){if(editor!=null)return;editor=new BladesKeyboard(a,title,initial,90,true,value->{action.accept(value);media.changed();},()->editor=null);}
  void closeEditor(){if(editor!=null)editor.close();}
  boolean touch(MotionEvent event,float x,float y){MainActivity.Dashboard d=a.dashboard;if(!open){if(x>=d.W-360&&x<=d.W-280&&y>=0&&y<=60){if(event.getAction()==MotionEvent.ACTION_UP)now();return true;}return false;}if(event.getAction()!=MotionEvent.ACTION_UP)return true;if(x>660||y>d.H-90){back();return true;}float top=screen==0?310:185;int n=offset+(int)((y-top)/45);if(y>=top&&n<labels().size()&&n<offset+slots()){if(n==selection)activate();else{selection=n;media.changed();}}return true;}
  void draw(Canvas c){MainActivity.Dashboard d=a.dashboard;if(!open){d.round(c,d.W-360,8,d.W-280,53,9,0x88416380);d.text(c,"Music",d.W-349,37,20,0xffe4f2ff,false,true);return;}d.rect(c,-d.offsetX/d.scale,0,d.W+d.offsetX/d.scale,d.H,0xaa000000);Path p=new Path();p.moveTo(0,0);p.lineTo(635,0);p.cubicTo(607,150,651,d.H-190,624,d.H);p.lineTo(0,d.H);p.close();d.fill(0xff668faf);c.drawPath(p,d.p);d.gradient(c,0,0,612,d.H,0xffc1d9e6,0xff547da4,true,0);String title=screen==0?"Now Playing":screen==1?"Playlists":screen==2||screen==3?playlist:screen==5?"Confirm deletion":"Capture options";d.text(c,d.fit(title,535,34),40,62,34,0xff102c43,false,false);float top=185;if(screen==0){top=310;RectF box=new RectF(40,92,202,254);d.round(c,box.left,box.top,box.right,box.bottom,8,0xff426a8a);media.image(c,media.albumArt,box);if(media.albumArt==null)d.text(c,"â™ª",92,195,60,0xffd7edfc,false,false);c.save();c.clipRect(224,100,590,275);d.wrapped(c,media.nowTitle.isEmpty()?"No track selected":media.nowTitle,224,123,350,24,0xff102c43);d.text(c,d.fit(media.nowArtist,350,19),224,235,19,0xff244c68,false,false);c.restore();d.text(c,d.fit(media.status,550,19),40,286,19,0xffe6f4ff,false,true);}else{String subtitle=screen==3?"Select a track to remove it":screen==5?"This cannot be undone":screen==4&&capture!=null?capture.name:"Select with A; back with B";d.text(c,d.fit(subtitle,550,22),40,127,22,0xff173b54,false,false);d.text(c,d.fit(media.status,550,18),40,157,18,0xffe6f4ff,false,true);}ArrayList<String> rows=labels();int count=screen==0?Math.max(3,(int)((d.H-410)/45)):slots();if(selection>=offset+count)offset=selection-count+1;for(int i=offset;i<Math.min(rows.size(),offset+count);i++){float y=top+(i-offset)*45;if(i==selection)d.gradient(c,27,y-4,588,y+38,0xfff0f7e7,0xffb6d1c5,true,8);d.text(c,d.fit(rows.get(i),520,24),44,y+26,24,0xff17354c,false,false);}d.text(c,"A Select   B Back   SELECT Music",40,d.H-35,22,0xffedf6ff,false,true);}
}
